case " ${__nvmimic_keep-} " in *" nvm_is_zsh "*) ;; *)
nvm_is_zsh() {
  [ -n "${ZSH_VERSION-}" ]
}
;; esac

case " ${__nvmimic_keep-} " in *" nvm_stdout_is_terminal "*) ;; *)
nvm_stdout_is_terminal() {
  [ -t 1 ]
}
;; esac

case " ${__nvmimic_keep-} " in *" nvm_echo "*) ;; *)
nvm_echo() {
  command printf %s\\n "$*" 2>/dev/null
}
;; esac

case " ${__nvmimic_keep-} " in *" nvm_echo_with_colors "*) ;; *)
nvm_echo_with_colors() {
  command printf %b\\n "$*" 2>/dev/null
}
;; esac

case " ${__nvmimic_keep-} " in *" nvm_cd "*) ;; *)
nvm_cd() {
  \cd "$@"
}
;; esac

case " ${__nvmimic_keep-} " in *" nvm_err "*) ;; *)
nvm_err() {
  (>&2 nvm_echo "$@") || return 0
}
;; esac

case " ${__nvmimic_keep-} " in *" nvm_err_with_colors "*) ;; *)
nvm_err_with_colors() {
