}
;; esac

case " ${__nvmimic_keep-} " in *" nvm_grep "*) ;; *)
nvm_grep() {
  GREP_OPTIONS='' command grep "$@"
}
;; esac

case " ${__nvmimic_keep-} " in *" nvm_has "*) ;; *)
nvm_has() {
  type "${1-}" >/dev/null 2>&1
}
;; esac

case " ${__nvmimic_keep-} " in *" nvm_has_executable "*) ;; *)
nvm_has_executable() {
  (
    # `|| true` so that shells with errexit-style options (eg, zsh's ERR_RETURN)
    # do not abort the subshell when the name is not an alias or a function
    unalias "${1-}" 2>/dev/null || true
    unset -f "${1-}" 2>/dev/null || true
    command -v "${1-}" >/dev/null 2>&1
  )
}
;; esac

case " ${__nvmimic_keep-} " in *" nvm_has_non_aliased "*) ;; *)
nvm_has_non_aliased() {
  nvm_has "${1-}" && ! nvm_is_alias "${1-}"
}
;; esac

case " ${__nvmimic_keep-} " in *" nvm_is_alias "*) ;; *)
nvm_is_alias() {
  # this is intentionally not "command alias" so it works in zsh.
  \alias "${1-}" >/dev/null 2>&1
}
;; esac

case " ${__nvmimic_keep-} " in *" nvm_command_info "*) ;; *)
nvm_command_info() {
  local COMMAND
  local INFO
  COMMAND="${1}"
  if type "${COMMAND}" | nvm_grep -q hashed; then
    INFO="$(type "${COMMAND}" | command sed -E 's/\(|\)//g' | command awk '{print $4}')"
  elif type "${COMMAND}" | nvm_grep -q aliased; then
    # shellcheck disable=SC2230
    INFO="$(which "${COMMAND}") ($(type "${COMMAND}" | command awk '{ $1=$2=$3=$4="" ;print }' | command sed -e 's/^\ *//g' -Ee "s/\`|'//g"))"
  elif type "${COMMAND}" | nvm_grep -q "^${COMMAND} is an alias for"; then
    # shellcheck disable=SC2230
    INFO="$(which "${COMMAND}") ($(type "${COMMAND}" | command awk '{ $1=$2=$3=$4=$5="" ;print }' | command sed 's/^\ *//g'))"
  elif type "${COMMAND}" | nvm_grep -q "^${COMMAND} is /"; then
    INFO="$(type "${COMMAND}" | command awk '{print $3}')"
  else
    INFO="$(type "${COMMAND}")"
  fi
  nvm_echo "${INFO}"
}
;; esac

case " ${__nvmimic_keep-} " in *" nvm_tree_contains_path "*) ;; *)
nvm_tree_contains_path() {
  local tree
  tree="${1-}"
  local node_path
  node_path="${2-}"

  if [ "@${tree}@" = "@@" ] || [ "@${node_path}@" = "@@" ]; then
    nvm_err "both the tree and the node path are required"
    return 2
  fi

  local clean_tree
  clean_tree="${tree}"

  # Strip trailing slashes in shell memory (e.g., "dir//" -> "dir")
  while [ "${clean_tree}" != "${clean_tree%/}" ]; do
    clean_tree="${clean_tree%/}"
  done
  if [ -z "${clean_tree}" ]; then
    clean_tree='/'
  fi

  # Pure in-memory POSIX parent-walk using parameter expansion instead of subshell dirname forks.
  # Uses literal string equality [ "${pathdir}" = "${clean_tree}" ] to prevent glob expansion bugs.
  local pathdir
  pathdir="${node_path}"
  while [ "${pathdir}" != '' ] && [ "${pathdir}" != '.' ] && [ "${pathdir}" != '/' ] &&
      [ "${pathdir}" != "${clean_tree}" ]; do
    case "${pathdir}" in
      */*)
        pathdir="${pathdir%/*}"
        if [ -z "${pathdir}" ]; then
          pathdir='/'
        fi
        ;;
      *)
        break
        ;;
    esac
  done
  [ "${pathdir}" = "${clean_tree}" ]
}
;; esac

case " ${__nvmimic_keep-} " in *" nvm_find_project_dir "*) ;; *)
nvm_find_project_dir() {
  local path_
  path_="${PWD}"
  while [ "${path_}" != "" ] && [ "${path_}" != '.' ] && [ ! -f "${path_}/package.json" ] && [ ! -d "${path_}/node_modules" ]; do
    path_=${path_%/*}
  done
  nvm_echo "${path_}"
}
;; esac

case " ${__nvmimic_keep-} " in *" nvm_find_up "*) ;; *)
nvm_find_up() {
  local path_
  path_="${PWD}"
  while [ "${path_}" != "" ] && [ "${path_}" != '.' ] && [ ! -f "${path_}/${1-}" ]; do
    path_=${path_%/*}
  done
  nvm_echo "${path_}"
}
;; esac

case " ${__nvmimic_keep-} " in *" nvm_find_nvmrc "*) ;; *)
nvm_find_nvmrc() {
  local dir
  dir="$(nvm_find_up '.nvmrc')"
  if [ -e "${dir}/.nvmrc" ]; then
    nvm_echo "${dir}/.nvmrc"
  fi
}
;; esac

case " ${__nvmimic_keep-} " in *" nvm_version_dir "*) ;; *)
nvm_version_dir() {
  local NVM_WHICH_DIR
  NVM_WHICH_DIR="${1-}"
  if [ -z "${NVM_WHICH_DIR}" ] || [ "${NVM_WHICH_DIR}" = "new" ]; then
    nvm_echo "${NVM_DIR}/versions/node"
  elif [ "_${NVM_WHICH_DIR}" = "_iojs" ]; then
    nvm_echo "${NVM_DIR}/versions/io.js"
  elif [ "_${NVM_WHICH_DIR}" = "_old" ]; then
    nvm_echo "${NVM_DIR}"
  else
    nvm_err 'unknown version dir'
    return 3
  fi
}
;; esac

case " ${__nvmimic_keep-} " in *" nvm_alias_path "*) ;; *)
nvm_alias_path() {
  nvm_echo "$(nvm_version_dir old)/alias"
}
;; esac

case " ${__nvmimic_keep-} " in *" nvm_hash_reset "*) ;; *)
nvm_hash_reset() {
  # under `set +h` there is no cache to clear, and `hash -r` errors
  if [ -n "${BASH_VERSION-}" ] && [ "${-#*h}" = "$-" ]; then
    return 0
  fi
  # `ksh93`'s `hash` takes no `-r` and its usage error is fatal; probing in a
  # subshell contains it, and spares the `ksh` variants that do accept `-r`
  if [ -n "${KSH_VERSION-}" ] && ! ( \hash -r ) >/dev/null 2>&1; then
    return 0
  fi
  \hash -r
}
;; esac

